from pathlib import Path
import importlib.util,os,subprocess
root=Path(__file__).resolve().parents[1];import tempfile;out=Path(tempfile.mkdtemp(prefix='auto-growth-gems-'))
spec=importlib.util.spec_from_file_location('cv',root/'Tools/cloud-validation.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
names=['SkillRuntime','GameTypes','ProgressionService','ProgressionService.Attachments','ProgressionService.AutomaticGrowth','CombatBalance','SkillDamageBudgets','HubTravelRules','MasteryCoreRuntime','TierRewardRules','TierRewardBand','ProgressionGoalState','ChapterProgression','ProgressionService.Chapter','ProgressionService.Reforge','ReforgeQuote','RoomTactics']
sources=[root/('Assets/Scripts/Core/'+n+'.cs') for n in names]+[root/'Tests/ProgressionTests.cs']
program='''using System;using Emberfall;class Program{static int n;static void Check(bool b,string s){n++;if(!b)throw new Exception(s);}static void Main(string[] a){for(int h=0;h<4;h++){var p=new ProgressionService(a[0]+h);p.NewGame((HeroClass)h);for(int level=1;level<=100;level++){p.Profile.level=level;p.Save();Check(p.LastError.Length==0,p.LastError);for(int k=0;k<GameBalance.SkillCount;k++){int want=0;for(int rank=1;rank<=3;rank++)if(level>=GameBalance.SkillRankRequiredLevel(k,rank))want=rank;Check(p.Profile.skillRanks[k]==want,"automatic rank");}Check(p.Profile.skillPoints==GameBalance.SkillPointBudget(level)-p.RefundableMasteryPoints,"mastery-only budget");}Check(p.LearnMastery((MasteryType)0),"mastery purchase");int points=p.Profile.skillPoints;Check(p.Load(),"reload");Check(p.Profile.skillPoints==points,"stable reload budget");Check(p.ResetMastery(true),"reset");Check(p.Profile.skillPoints==GameBalance.SkillPointBudget(100),"full refund");Check(p.Profile.skillRanks[9]==3,"reset preserves automatic skills");var q=new ProgressionService(a[0]+h+"xp");q.NewGame((HeroClass)h);bool observed=false;q.LeveledUp+=l=>{if(l==4){observed=true;Check(q.Profile.skillRanks[1]>0,"learned before callback");}};q.GrantExperience(GameBalance.XpToNext(1)+GameBalance.XpToNext(2)+GameBalance.XpToNext(3));Check(observed,"level events");}for(int h=0;h<4;h++){var p=new ProgressionService(a[0]+"gem"+h);p.NewGame((HeroClass)h);p.Profile.level=100;p.Profile.mechanicMaterials=10000;p.Save();Check(BuildCatalog.GemsFor((HeroClass)h).Length>=10,"gem catalog");foreach(var gem in BuildCatalog.GemsFor((HeroClass)h)){if(!BuildCatalog.IsAttributeGem(gem))continue;for(int t=0;t<4;t++){var rarity=(Rarity)t;int before=p.Profile.mechanicMaterials;var quote=p.PrepareMerchantPurchase(gem,true,rarity);Check(quote!=null,"rarity quote");Check(p.BuyAtMerchant(quote,true),p.LastError);Check(p.Profile.mechanicMaterials==before-BuildCatalog.GemPrice(rarity),"tier price");Check(p.Attachment(gem).rarity==rarity,"actual quality");Check(!p.BuyAtMerchant(quote,true),"duplicate purchase rejected");}Check(p.SetAttachmentMounted(gem,true,true),"mount any class");int count=0;foreach(var v in p.Profile.attachments)if(v.mounted&&BuildCatalog.MechanicSlot(v.mechanic)==BuildCatalog.MechanicSlot(gem))count++;Check(count==1,"one per slot");var equipped=p.GetStats();Check(p.SetAttachmentMounted(gem,false,true),"unmount");var plain=p.GetStats();int type=BuildCatalog.GemAttribute(gem);Check(type==0?equipped.Damage>plain.Damage:type==1?equipped.CritChance>plain.CritChance:equipped.CritDamageBonus>plain.CritDamageBonus,"actual attribute bonus");Check(p.Load(),"gem reload");Check(p.Attachment(gem).rarity==Rarity.Legendary,"rarity survives reload");}Check(p.PrepareMerchantPurchase(EquipmentMechanic.WeaponPower,false)==null,"camp gate");}var achievements=new ProgressionService(a[0]+"achievements");achievements.NewGame(HeroClass.Vanguard);Check(!achievements.ClaimAchievement("level/10"),"early claim rejected");achievements.Profile.level=10;achievements.Save();int oldGold=achievements.Profile.gold,oldShards=achievements.Profile.mechanicMaterials;Check(achievements.ClaimAchievement("level/10"),"claim");Check(achievements.Profile.gold==oldGold+100&&achievements.Profile.mechanicMaterials==oldShards+2,"actual rewards");Check(!achievements.ClaimAchievement("level/10"),"duplicate claim");Check(achievements.Load(),"achievement reload");Check(achievements.AchievementClaimed("level/10")&&!achievements.ClaimAchievement("level/10"),"claim durable");achievements.Profile.level=30;achievements.Save();System.IO.Directory.CreateDirectory(achievements.SaveFilePath+".tmp");Check(!achievements.ClaimAchievement("level/30"),"failed persistence");Check(!achievements.AchievementClaimed("level/30"),"failed claim not consumed");System.IO.Directory.Delete(achievements.SaveFilePath+".tmp");Check(achievements.ClaimAchievement("level/30"),"retry after failure");var goals=new ProgressionService(a[0]+"goals");goals.NewGame(HeroClass.Vanguard);goals.Profile.level=100;goals.Profile.highestAdventureTier=9;goals.Profile.growthRewardReceipts.AddRange(new[]{"growth/0/practice","growth/0/core/3","growth/0/tier/1","growth/0/tier/5","growth/0/upgrade/3","growth/0/variant/3"});goals.Save();var target=goals.SelectedProgressionGoal(true);Check(target.Title.Contains("Lv100")&&target.RequiredAdventureTier==10&&!target.Done,"level dungeon goal");goals.Profile.highestAdventureTier=10;goals.Save();Check(goals.SelectedProgressionGoal(true).Done,"goal completes");int goldBefore=goals.Profile.gold;Check(goals.AdvanceAutomaticGrowth(),"legacy caller safe");Check(goals.Profile.gold==goldBefore,"no automatic goal rewards");Check(ProgressionService.Achievements.Length==59,"fixed achievement catalog");var ids=new System.Collections.Generic.HashSet<string>();foreach(var achievement in ProgressionService.Achievements){Check(ids.Add(achievement.Id),"unique achievement");Check(achievement.Target>0&&achievement.Gold>0,"valid reward");}var legacy=new ProgressionService(a[0]+"legacygoal");legacy.NewGame(HeroClass.Vanguard);legacy.Profile.growthRewardReceipts.Add("growth/0/practice");legacy.Profile.growthRewardReceipts.Add("growth/0/tier/5");legacy.Save();Check(legacy.AchievementClaimed("trial/0/2")&&legacy.AchievementClaimed("dungeon/50"),"legacy rewards migrate");Check(!legacy.ClaimAchievement("trial/0/2"),"legacy reward not duplicated");var trial=Array.Find(ProgressionService.Achievements,t=>t.Id=="trial/0/0");legacy.Profile.tutorialMask=1;Check(trial.Progress(legacy.Profile)==1,"trial evidence");for(int tier=1;tier<=10;tier++){int epic=0,legendary=0,bossEpic=0,bossLegendary=0;for(int roll=0;roll<100;roll++){var normal=TierRewardRules.DropRarity(false,tier,roll);var boss=TierRewardRules.DropRarity(true,tier,roll);if(normal==Rarity.Epic)epic++;if(normal==Rarity.Legendary)legendary++;if(boss==Rarity.Epic)bossEpic++;if(boss==Rarity.Legendary)bossLegendary++;}Check(epic<=6&&legendary==1,"ordinary rarity reduced");Check(bossEpic<=14&&bossLegendary<=4,"boss rarity reduced");for(int mode=-1;mode<=3;mode++){int high=0;for(int roll=0;roll<100;roll++)if(AdventureRewardRules.EquipmentRarity(mode,tier,roll)>=Rarity.Epic)high++;Check(high<=16,"clear high rarity bounded");Check(AdventureRewardRules.MinimumRarity(mode)==Rarity.Rare,"no guaranteed epic");}}Console.WriteLine(n+" checks passed");}}'''
proj=m.write_project(out/'project',sources,program);env=dict(os.environ,DOTNET_CLI_HOME=str(out/'cli'))
r=subprocess.run(['/Applications/Unity/Hub/Editor/6000.6.4f1/Unity.app/Contents/Resources/Scripting/DotNetSdk/dotnet','run','--project',str(proj),'--',str(out/'saves')],env=env,capture_output=True,text=True);print(r.stdout,r.stderr);raise SystemExit(r.returncode)
